type Scope={userId:string,business:Row,catalog:Row,businessId:string,locationId:string,perform:(action:string,initial?:Row)=>void,showDocument:(document:Row)=>void,notify:(message:string)=>void,canAction:(action:string)=>boolean};
const ScopeContext=createContext<Scope|null>(null);
export const useScope=()=>useContext(ScopeContext)!;
export function useResource(path:string,enabled=true){const{businessId,locationId}=useScope();return useQuery({queryKey:[path,businessId,locationId],queryFn:()=>api.get(path),enabled});}
export function hasPermission(business:Row,...permissions:string[]){const grants=business.membership?.permissions||[];return grants.includes('*')||permissions.some(p=>grants.includes(p)||grants.includes(p.split('.')[0]+'.*'));}
function showNavigation(business:Row,key:string){const names:Record<string,string[]>={overview:[],operations:['cash_shifts.open','cash_shifts.view','cash_shifts.review','cash_shifts.manage','cash_shifts.handover','purchases.rfq','statements.view','statements.import','runtime.manage','inventory.count','inventory.count_record','inventory.count_manage','inventory.count_review','inventory.measure','inventory.scale_manage','purchases.claim','purchases.approve','messaging.send','accounting.close','delivery.view','delivery.post','delivery.confirm','delivery.manage','jobs.view','jobs.manage','jobs.plan','payroll.view','sales.view','purchases.view','production.view','production.plan','inventory.view','quality.view','quality.post','maintenance.view','maintenance.post','accounting.view','finance.view'],customers:['sales.view'],suppliers:['purchases.view'],sales:['sales.view','sales.post'],production:['production.view','production.post'],inventory:['inventory.view'],purchases:['purchases.view','purchases.post'],transfers:['transfers.view','transfers.post'],money:['finance.view','finance.post','sales.collect','purchases.pay'],employees:['payroll.view','payroll.post'],accounting:['accounting.view','reports.view','finance.view','inventory.view','sales.view','purchases.view','payroll.view'],settings:['settings.manage','users.manage','accounting.view','accounting.tax_view','accounting.tax_manage','accounting.tax_confirm']};return key==='overview'||hasPermission(business,...(names[key]||[]));}
const links:{path:string,key:string,icon:LucideIcon}[]=[{path:'/',key:'overview',icon:LayoutDashboard},{path:'/sales',key:'sales',icon:ShoppingBag},{path:'/customers',key:'customers',icon:Users},{path:'/suppliers',key:'suppliers',icon:Building2},{path:'/production',key:'production',icon:Factory},{path:'/inventory',key:'inventory',icon:Boxes},{path:'/purchases',key:'purchases',icon:ShoppingCart},{path:'/transfers',key:'transfers',icon:ArrowRightLeft},{path:'/money',key:'money',icon:Wallet},{path:'/employees',key:'employees',icon:Users},{path:'/accounting',key:'accounting',icon:ChartNoAxesCombined},{path:'/operations',key:'operations',icon:ClipboardList},{path:'/settings',key:'settings',icon:Settings}];
const productName=(id:unknown,catalog:Row)=>catalog.products?.find((p:Row)=>p.id===Number(id))?.name??String(id??'—');
const warehouseName=(id:unknown,catalog:Row)=>catalog.warehouses?.find((p:Row)=>p.id===Number(id))?.name??String(id??'—');
const partyName=(id:unknown,catalog:Row)=>catalog.parties?.find((p:Row)=>p.id===Number(id))?.name??'مشتری حضوری';
const dateLabel=formatCalendarDate;

export default function App(){const{i18n}=useTranslation();useEffect(()=>{documentGlobalDir(i18n.language);},[i18n.language]);const queryClient=useQueryClient();const session=useQuery({queryKey:['session'],queryFn:()=>api.get('/api/session/'),retry:false});if(session.isLoading)return <div className="boot"><Brand/><Spinner/></div>;if(session.isError)return <div className="boot"><Brand/><ErrorNotice error={session.error} retry={()=>session.refetch()}/><OfflineNotebookEntry/></div>;if(!session.data?.user)return <Login onLogin={()=>queryClient.invalidateQueries({queryKey:['session']})}/>;return <CalendarProvider userId={session.data.user.id}><ReviewProvider>{session.data.user.portal_only?<PortalWorkspace/>:<Workspace user={session.data.user}/>}</ReviewProvider></CalendarProvider>;}
function Brand(){return <div className="brand"><span className="brand-mark"><span/><span/><span/></span><div><strong>{l("نوا")}<span>NAWA</span></strong><small>{l("سیستم تولید و حسابداری")}</small></div></div>}
function Login({onLogin}:{onLogin:()=>void}){const{t,i18n}=useTranslation();return <div className="login-page"><section className="login-art"><Brand/><div><div className="eyebrow light">{l("از مواد اولیه تا آخرین حساب")}</div><h1>{l("کسب‌وکارتان را")}<br/>{l("با دید روشن")}<br/><em>{l("مدیریت کنید.")}</em></h1><p>{l("تولید، انبار، فروش و حسابداری؛ پیوسته در یک فضای کاری ساده و منظم.")}</p></div><span className="login-footer">{l("طراحی‌شده برای جریان واقعی کار شما")}</span><div className="art-blocks"><i/><i/><i/></div></section><section className="login-form"><div className="login-card"><label className="login-language"><span>{t('language')}</span><select aria-label={t('language')} value={i18n.language} onChange={e=>{i18n.changeLanguage(e.target.value);localStorage.setItem('nawa.language',e.target.value);}}><option value="fa">{l('دری')}</option><option value="ps">{l('پښتو')}</option><option value="en">English</option></select></label><Badge>{l("ورود امن به فضای کار")}</Badge><h2>{l("خوش آمدید")}</h2><p>{l("برای ادامه، با حساب کاربری اختصاصی خود وارد شوید.")}</p><SimpleForm fields={[{key:'username',label:'نام کاربری',required:true,placeholder:'نام کاربری شما'},{key:'password',label:'رمز عبور',type:'password',required:true},{key:'otp',label:'کد تأیید دومرحله‌ای (در صورت فعال بودن)',placeholder:'اختیاری'}]} onSubmit={async v=>{await api.post('/api/session/',v);onLogin();}} submit="ورود به سیستم"/><OfflineNotebookEntry/><div className="secure-note"><ShieldCheck size={17}/>{l("اطلاعات فقط در کسب‌وکارهای مجاز شما نمایش داده می‌شود.")}</div></div><small className="login-help">{l("برای ساخت یا بازیابی حساب، با مدیر سیستم خود تماس بگیرید.")}</small></section></div>}
function savedScope(userId:unknown){try{const value=JSON.parse(sessionStorage.getItem(`nawa:scope:${userId}`)||'{}');return {businessId:/^\d+$/.test(value.businessId||'')?String(value.businessId):'',locationId:/^\d+$/.test(value.locationId||'')?String(value.locationId):''};}catch{return {businessId:'',locationId:''};}}
function saveScope(userId:unknown,businessId:string,locationId:string){try{sessionStorage.setItem(`nawa:scope:${userId}`,JSON.stringify({businessId,locationId}));}catch{/* Scope remains available for this page when browser storage is disabled. */}}
function Workspace({user}:{user:Row}){const{mode:calendar,setMode:saveCalendar}=useCalendarPreferences();useDismissActionMenus();const{t,i18n}=useTranslation();const qc=useQueryClient();const context=useQuery({queryKey:['context'],queryFn:()=>api.get('/api/context/')});const[businessId,setBusinessId]=useState(()=>savedScope(user.id).businessId);const[locationId,setLocationId]=useState(()=>savedScope(user.id).locationId);const[mobile,setMobile]=useState(false);const[action,setAction]=useState('');const[actionInitial,setActionInitial]=useState<Row>({});const[toast,setToast]=useState('');const[search,setSearch]=useState('');const[help,setHelp]=useState(false);const navigate=useNavigate();const location=useLocation();const activeId=(context.data?.businesses?.some((b:Row)=>String(b.id)===businessId)?businessId:'')||String(context.data?.businesses?.[0]?.id||'');configureScope(activeId,locationId);const schema=useQuery({queryKey:['schema',activeId],queryFn:()=>api.get('/api/schema/'),enabled:!!activeId});const catalog=useQuery({queryKey:['catalog',activeId,locationId,i18n.language],queryFn:()=>api.get('/api/catalog/'),enabled:!!activeId,placeholderData:(previous,query)=>query?.queryKey[1]===activeId&&query?.queryKey[2]===locationId?previous:undefined});const business=context.data?.businesses?.find((b:Row)=>String(b.id)===activeId);useEffect(()=>{if(context.data&&businessId&&activeId!==businessId){setBusinessId(activeId);setLocationId('');saveScope(user.id,activeId,'');}},[context.data,activeId,businessId,user.id]);useEffect(()=>{if(catalog.data&&locationId&&!catalog.data.locations?.some((w:Row)=>String(w.id)===locationId)){setLocationId('');saveScope(user.id,activeId,'');}},[catalog.data,locationId,activeId,user.id]);useEffect(()=>{setMobile(false);},[location.pathname]);useEffect(()=>{if(toast){const timer=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(timer);}},[toast]);if(context.isLoading)return <div className="boot"><Spinner/></div>;if(context.isError)return <div className="boot"><ErrorNotice error={context.error}/></div>;if(!business)return <div className="boot"><Brand/><Empty text="شما هنوز به کسب‌وکاری دسترسی ندارید"/><button className="button secondary" onClick={async()=>{await api.post('/api/logout/',{});qc.clear();window.location.reload();}}>{l("خروج")}</button></div>;
const scope:Scope={userId:String(user.id),business,catalog:catalog.data||{},businessId:activeId,locationId,perform:(a:string,initial:Row={})=>{window.document.querySelectorAll<HTMLDetailsElement>('details.advanced-actions[open], details.action-menu[open]').forEach(el=>el.open=false);setActionInitial(initial);setAction(a);},showDocument:(d:Row)=>navigate(`/documents/${d.id}?business=${activeId}`,{state:{from:location.pathname+location.search}}),notify:(message:string)=>setToast(l(message)),canAction:(a:string)=>hasPermission(business,"*")||(schema.data?.operations||[]).some((o:Row)=>o.action===(a==="sale_return"?"sales_return":a))};
return <ScopeContext.Provider value={scope}><ReviewScope scopeKey={`${user.id}:${activeId}:${locationId}:${location.pathname}`}/><div className="app-shell"><aside className={`sidebar ${mobile?'visible':''}`}><Brand/><nav id="main-navigation" aria-label={l('فهرست اصلی')}>{[{label:'کارهای روزانه',keys:['overview','sales','customers','purchases','suppliers','production','inventory','transfers']},{label:'مالی و کارمندان',keys:['money','employees','accounting']},{label:'مدیریت',keys:['operations','settings']}].map(group=>{const allowed=group.keys.flatMap(key=>links.filter(item=>item.key===key&&showNavigation(business,item.key)));return allowed.length?<div className="nav-group" key={group.label}><div className="sidebar-caption">{l(group.label)}</div>{allowed.map(({path,key,icon:Icon})=><NavLink key={path} to={path} end={path==='/'} className={({isActive})=>isActive?'nav-item active':'nav-item'}><Icon size={20}/><span>{t(key)}</span>{key==='operations'&&<AttentionBadge/>}</NavLink>)}</div>:null;})}</nav><div className="sidebar-bottom"><button className="sidebar-help" onClick={()=>setHelp(true)}><CircleHelp size={20}/><div><strong>{l('راهنمای کارهای روزانه')}</strong><small>{l('از کجا شروع کنم؟')}</small></div><ArrowLeft size={16}/></button><button className="nav-item logout" onClick={async()=>{await api.post('/api/logout/',{});qc.clear();window.location.reload();}}><LogOut size={19}/><span>{t('logout')}</span></button><div className="sidebar-version">{l("نوا")}<span>Manufacturing ERP · 0.1</span></div></div></aside>{mobile&&<div className="sidebar-scrim" onClick={()=>setMobile(false)}/>}
<div className="main-shell"><header className="topbar"><div className="topbar-start"><button className="icon-button menu-toggle" aria-label={l("باز کردن فهرست")} aria-expanded={mobile} aria-controls="main-navigation" onClick={()=>setMobile(!mobile)}><Menu size={22}/></button><div className="business-switch"><Building2 size={20}/><select aria-label={t('business')} value={activeId} onChange={e=>{saveScope(user.id,e.target.value,'');setAction('');setSearch('');setBusinessId(e.target.value);setLocationId('');configureScope(e.target.value);qc.invalidateQueries();}}>{context.data?.businesses?.map((b:Row)=><option key={b.id} value={b.id}>{b.name}</option>)}</select><ChevronDown size={14}/></div><div className="topbar-divider"/><select className="location-select" aria-label={t('location')} value={locationId} onChange={e=>{saveScope(user.id,activeId,e.target.value);setAction('');setLocationId(e.target.value);configureScope(activeId,e.target.value);}}><option value="">{l("تمام موقعیت‌های مجاز")}</option>{catalog.data?.locations?.map((l:Row)=><option key={l.id} value={l.id}>{l.name}</option>)}</select></div><div className="topbar-end"><AttentionBell/><GlobalCreate/><OfflineNotebookEntry userId={String(user.id)} businessId={activeId}/><select className="calendar-select" aria-label={l('تقویم')} value={calendar} onChange={e=>{saveCalendar(e.target.value as CalendarMode).catch(error=>setToast(String(error)));}}><option value="gregorian">{l('میلادی')}</option><option value="jalali">{l('هجری شمسی')}</option></select><button className="icon-button help-toggle" aria-label={l("راهنمای کارهای روزانه")} onClick={()=>setHelp(true)}><CircleHelp size={20}/></button><ConnectionHealth/><select className="language-select" value={i18n.language} aria-label={t('language')} onChange={e=>{i18n.changeLanguage(e.target.value);localStorage.setItem('nawa.language',e.target.value);api.patch('/api/preferences/',{language:e.target.value}).catch(error=>setToast(String(error)));}}><option value="fa">{l("دری")}</option><option value="ps">{l("پښتو")}</option><option value="en">EN</option></select><div className="topbar-divider"/><button className="user-profile" aria-label={l("امنیت حساب من")} onClick={()=>navigate('/account')}><span className="avatar">{String(user.name||user.username).slice(0,1)}</span><div><strong>{user.name||user.username}</strong><small>{l(business.membership?.permissions?.includes('*')?'مدیر کسب‌وکار':'کاربر مجاز')}</small></div></button></div></header>
<main className="workspace"><CashCustodyBanner/><div className="workspace-tools"><div className="breadcrumb"><span>{l("فضای کاری")}</span><span>/</span><strong>{t(links.find(l=>l.path===location.pathname||(l.path!=='/'&&location.pathname.startsWith(l.path+'/')))?.key||'overview')}</strong></div><form className="global-search" onSubmit={e=>{e.preventDefault();navigate(`/sales?q=${encodeURIComponent(search)}`);}}><Search size={17}/><input placeholder={l('جستجوی بل فروش…')} aria-label={l('جستجوی بل فروش…')} value={search} onChange={e=>setSearch(e.target.value)}/><kbd>↵</kbd></form></div>{catalog.isError&&<ErrorNotice error={catalog.error} retry={()=>catalog.refetch()}/>}<ContextualGuidance/><DailyShortcuts/>{catalog.isLoading?<Spinner/>:<Routes><Route path="/documents/:documentId/correct" element={<CorrectionWorkspace/>}/><Route path="/documents/:documentId" element={<DocumentDetailPage/>}/><Route path="/help" element={<LearningCentre/>}/><Route path="/sales/counter" element={<CounterSalesWorkspace/>}/><Route path="/" element={<Dashboard/>}/><Route path="/sales" element={<Sales/>}/><Route path="/customers" element={<PartyCenter/>}/><Route path="/suppliers" element={<PartyCenter supplier/>}/><Route path="/production" element={<Production/>}/><Route path="/inventory" element={<Inventory/>}/><Route path="/purchases" element={<Purchases/>}/><Route path="/transfers" element={<Transfers/>}/><Route path="/money" element={<Money/>}/><Route path="/employees" element={<Employees/>}/><Route path="/employees/:employeeId" element={<EmployeeStatementPage/>}/><Route path="/accounting" element={<Accounting/>}/><Route path="/operations" element={<GrowthWorkspace/>}/><Route path="/settings" element={<SettingsPage/>}/><Route path="/account" element={<UserSecurity/>}/><Route path="*" element={<Empty text="صفحه پیدا نشد"/>}/></Routes>}<footer className="workspace-footer"><span>{l("نوا · مدیریت متصل تولید و حسابداری")}</span><span><ShieldCheck size={13}/>{l("ثبت دقیق، تصمیم روشن")}</span></footer></main></div>{action&&<Modal title={l(operationLabels[action]||action)} subtitle="بخش‌های لازم را تکمیل کنید؛ سپس خلاصه را بررسی و ثبت کنید." onClose={()=>setAction('')} wide><OperationForm action={action} initial={actionInitial} onSuccess={d=>{setAction('');setToast('عملیات با موفقیت ثبت شد.');qc.invalidateQueries();if(d)scope.showDocument(d);}}/></Modal>}{help&&<Modal title={l('راهنمای کارهای روزانه')} subtitle="کار مورد نظر را انتخاب کنید تا به بخش مربوط بروید." onClose={()=>setHelp(false)}><div className="help-tasks"><button onClick={()=>{setHelp(false);navigate('/help');}}><CircleHelp size={21}/><div><strong>{l('مرکز یادگیری')}</strong><p>{l('رهنمای عملی دری')}</p></div><ArrowLeft size={18}/></button>{[{title:'فروش به مشتری',text:'محصول و ضخامت را انتخاب کنید. مبلغ دریافت‌شده و مانده بل را همان‌جا ببینید.',path:'/sales',key:'sales',icon:ShoppingBag},{title:'ثبت تولید امروز',text:'مواد واقعاً مصرف‌شده و خروجی تولید را ثبت کنید؛ فرمول اجباری نیست.',path:'/production',key:'production',icon:Factory},{title:'بررسی موجودی انبار',text:'بلوک، ابعاد و ارتفاع باقی‌مانده را پیدا کنید و از همان بلوک فروش بسازید.',path:'/inventory',key:'inventory',icon:Boxes},{title:'دریافت باقی‌مانده بل',text:'در بخش فروش، بل دارای مانده را باز کنید و دریافت وجه را انتخاب کنید.',path:'/sales',key:'sales',icon:Wallet},{title:'ارسال به کابل',text:'انتقال جدید بسازید. شعبه مقصد دریافت را تأیید می‌کند.',path:'/transfers',key:'transfers',icon:ArrowRightLeft}].filter(item=>showNavigation(business,item.key)).map(({icon:Icon,...item})=><button key={item.title} onClick={()=>{setHelp(false);navigate(item.path);}}><span><Icon size={21}/></span><div><strong>{l(item.title)}</strong><p>{l(item.text)}</p></div><ArrowLeft size={18}/></button>)}</div></Modal>} {toast&&<div className="toast"><Check size={20}/>{l(toast)}<button onClick={()=>setToast('')} aria-label={l("بستن")}><X size={16}/></button></div>}</div></ScopeContext.Provider>}
function useDismissActionMenus(){useEffect(()=>{const dismiss=(event:Event)=>{if(event.type==='keydown'&&(event as KeyboardEvent).key!=='Escape')return;if(event.type==='pointerdown'&&(event.target as Element)?.closest('details.advanced-actions, details.action-menu'))return;window.document.querySelectorAll<HTMLDetailsElement>('details.advanced-actions[open], details.action-menu[open]').forEach(el=>el.open=false);};window.document.addEventListener('pointerdown',dismiss);window.document.addEventListener('keydown',dismiss);return()=>{window.document.removeEventListener('pointerdown',dismiss);window.document.removeEventListener('keydown',dismiss);};},[]);}
function documentGlobalDir(language:string){window.document.documentElement.dir=language==='en'?'ltr':'rtl';window.document.documentElement.lang=language==='fa'?'fa-AF':language==='ps'?'ps-AF':'en';window.document.title=`${l('نوا')} | ${l('حسابداری و تولید')}`;}
export function ActionButton({action,secondary=false,children}:{action:string,secondary?:boolean,children?:ReactNode}){const{perform,canAction}=useScope();if(!canAction(action))return null;return <button className={`button ${secondary?'secondary':'primary'}`} onClick={()=>perform(action)}><Plus size={17}/>{l(children||operationLabels[action])}</button>}
function documentColumns(catalog:Row):Column[]{return [{key:'number',label:'شماره سند',render:r=><span className="document-number">{r.number}</span>},{key:'date',label:'تاریخ',sortType:'date',render:r=>dateLabel(r.date)},{key:'party',label:'طرف حساب',sortValue:r=>r.party_name||(r.party?partyName(r.party,catalog):r.data?.customer_name||''),filterValue:r=>r.party_name||(r.party?partyName(r.party,catalog):r.data?.customer_name||''),render:r=>r.party_name||(r.party?partyName(r.party,catalog):r.data?.customer_name||r.reference||'—')},{key:'amount',label:'مبلغ',sortType:'decimal',total:{precision:2,suffix:'AFN'},render:r=><strong className="numeric">{money(r.amount)}</strong>},{key:'balance',label:'باقی‌مانده',sortType:'decimal',render:r=><span className={Number(r.balance)>0?'text-amber':'text-muted'}>{money(r.balance)}</span>},{key:'state',label:'وضعیت',render:r=><Status value={r.state==='posted'&&['sale','purchase_bill'].includes(r.kind)?(Number(r.balance)>0?(Number(r.balance)<Number(r.amount)?'partial':'unpaid'):'paid'):r.state}/>}];}
function DocumentsPanel({kind,title}:{kind:string,title:string}){const{catalog}=useScope();return <Panel title={title} subtitle="روی هر سند کلیک کنید تا جزئیات آن باز شود"><DocumentRegister kind={kind} columns={documentColumns(catalog)}/></Panel>}
export function DocumentWorkspace({tabs}:{tabs:[string,string][]}){const[active,setActive]=useState(tabs[0][0]);return <><div className="page-tabs" onKeyDown={tabNavigation} role="tablist" aria-label={l('اسناد')}>
{tabs.map(([key,title])=><button role="tab" aria-selected={active===key} key={key} className={active===key?'active':''} onClick={()=>setActive(key)}>{l(title)}</button>)}
</div><DocumentsPanel key={active} kind={active} title={l(tabs.find(([key])=>key===active)?.[1]||'اسناد')}/></>;}
function Dashboard(){return <DailyWorkspace overview={<BusinessOverview/>}/>;}
function Sales(){
 const navigate=useNavigate();const{t}=useTranslation();const{catalog,perform}=useScope();const query=useLocation().search;const search=new URLSearchParams(query).get('q')||'';const[view,setView]=useState(new URLSearchParams(query).get('view')||'sale');
 useEffect(()=>setView(new URLSearchParams(query).get('view')||'sale'),[query]);
 return <><SectionHead title={t('sales')} description="از برش دقیق بلوک تا پیگیری آخرین افغانی بل مشتری." actions={<><ActionButton action="receipt" secondary>{l('دریافت پول')}</ActionButton><ActionButton action="sale">{l('فروش جدید')}</ActionButton></>}/><details className="advanced-actions"><summary><Plus size={16}/>{l('عملیات بیشتر')}<ChevronDown size={15}/></summary><div className="action-row"><ActionButton action="quotation" secondary/><ActionButton action="sales_order" secondary/><ActionButton action="order_cancel" secondary/></div></details>
 <div className="page-tabs" onKeyDown={tabNavigation} role="tablist" aria-label={l('دفتر فروش')}>{[['sale','بل‌های فروش'],['sales_order','سفارش‌های فروش'],['quotation','پیش‌فاکتورها']].map(([key,title])=><button role="tab" aria-selected={view===key} className={view===key?'active':''} key={key} onClick={()=>{setView(key);const params=new URLSearchParams(query);params.set('view',key);navigate(`/sales?${params.toString()}`);}}>{l(title)}</button>)}</div>
 {view==='sale'?<Panel title={l('بل‌های فروش')} subtitle="مشتریان دائمی و حضوری، در یک دفتر فروش"><DocumentRegister kind="sale" search={search} columns={[...documentColumns(catalog),{key:'collect',label:'',sortable:false,render:r=>Number(r.balance)>0?<button className="text-link" onClick={e=>{e.stopPropagation();perform('receipt',{invoice:r.id,amount:r.balance});}}>{l('دریافت وجه')}<ArrowLeft size={14}/></button>:<span className="text-muted"><Check size={16}/></span>}]}/></Panel>:<DocumentsPanel key={view} kind={view} title={l(view==='sales_order'?'سفارش‌های فروش':'پیش‌فاکتورها')}/>}
 <div className="info-card"><CircleHelp size={20}/><div><strong>{l('فروش و دریافت پول دو رویداد جدا هستند.')}</strong><p>{l('با هر دریافت، مانده همان بل کم می‌شود؛ مبلغ فروش دوباره ثبت نمی‌شود.')}</p></div><button className="button secondary small" onClick={()=>perform('sale_return')}>{l('ثبت برگشت فروش')}</button></div></>;
}
function Production(){const{t}=useTranslation();const{business,businessId,locationId}=useScope();return <><FactoryReviewPanel/><ProductionProcessBoard key={`${businessId}:${locationId}`}/><SectionHead title={t('production')} description="مواد مصرف‌شده واقعی، بلوک‌های تولیدی و هزینه هر بچ را ثبت کنید." actions={<><ActionButton action="trim" secondary>{l("اصلاح و سربلوک")}</ActionButton><ActionButton action="production">{l("ثبت بچ تولید")}</ActionButton></>}/><div className="mode-banner"><span className="mode-icon"><Factory size={25}/></span><div><strong>{l(String(business.manufacturing_mode).toLowerCase()==='bom'?'تولید با کمک فرمول تأییدشده':'تولید بر اساس مصرف واقعی')}</strong><p>{l(String(business.manufacturing_mode).toLowerCase()==='bom'?'مصرف واقعی مستقل از مقادیر پیش‌بینی‌شده ثبت می‌شود.':'تعداد بلوک‌ها و مواد واقعاً مصرف‌شده را وارد کنید؛ نیازی به ثبت فرمول نیست.')}</p></div><Badge>{l(String(business.manufacturing_mode).toLowerCase()==='bom'?'BOM فعال':'بدون فرمول اجباری')}</Badge></div><div className="flow-steps">{[{n:'۰۱',title:'مواد اولیه',sub:'ورود و انتقال به کف تولید'},{n:'۰۲',title:'مصرف واقعی',sub:'ثبت مقدار استفاده‌شده'},{n:'۰۳',title:'تولید و اصلاح',sub:'اندازه‌گیری و فرآورده جانبی'},{n:'۰۴',title:'آماده فروش',sub:'موجودی و بهای تمام‌شده'}].map(s=><div key={s.n}><b>{l(s.n)}</b><div><strong>{l(s.title)}</strong><small>{l(s.sub)}</small></div><ArrowLeft size={17}/></div>)}</div><DocumentsPanel kind="production" title={l("بچ‌های تولید")}/><div className="two-columns"><DocumentsPanel kind="trim" title={l("اصلاح و سربلوک / کف بلوک")}/><Panel title={l("عملیات مواد")} subtitle="مواد صادرشده با مواد مصرف‌شده یکسان نیست"><div className="action-list"><ActionButton action="production_start" secondary/><ActionButton action="production_consume" secondary/><ActionButton action="production_complete" secondary/><ActionButton action="material_issue" secondary>{l("انتقال مواد به کف تولید")}</ActionButton><ActionButton action="material_return" secondary>{l("برگشت مواد استفاده‌نشده")}</ActionButton>{String(business.manufacturing_mode).toLowerCase()==='bom'&&<ActionButton action="production_bom" secondary>{l("تولید با نسخه فرمول")}</ActionButton>}</div></Panel></div></>}
function Inventory(){const navigate=useNavigate();const{catalog,perform,businessId,business,canAction}=useScope();const q=useResource('/api/stock/');const[tab,setTab]=useState('blocks');const[search,setSearch]=useState('');const blocks=(q.data?.blocks||[]).filter((r:Row)=>(r.code+' '+productName(r.product,catalog)).toLowerCase().includes(search.toLowerCase()));return <><SectionHead title={l("موجودی و انبار")} description="هر بلوک با هویت، ابعاد و ارتفاع باقی‌مانده واقعی." actions={<><ActionButton action="stock_adjust" secondary>{l("شمارش و اصلاح موجودی")}</ActionButton><ActionButton action="transfer_dispatch">{l("انتقال موجودی")}</ActionButton></>}/><details className="advanced-actions"><summary><Plus size={16}/>{l("عملیات بیشتر")}<ChevronDown size={15}/></summary><div className="action-row"><ActionButton action="stock_count" secondary/><ActionButton action="stock_count_adjust" secondary/><ActionButton action="reserve" secondary/><ActionButton action="reservation_release" secondary/><ActionButton action="cut" secondary/><ActionButton action="quality_release" secondary/></div></details><div className="inventory-toolbar"><div className="tabs pill"><button className={tab==='blocks'?'active':''} onClick={()=>setTab('blocks')}><Boxes size={17}/>{l("بلوک‌ها و قطعات")}</button><button className={tab==='pools'?'active':''} onClick={()=>setTab('pools')}><Package size={17}/>{l("تمام موجودی")}</button></div>{tab==='blocks'&&<div className="search-input"><Search size={17}/><input placeholder={l("جستجوی محصول یا کد بلوک")} value={search} onChange={e=>setSearch(e.target.value)}/></div>}</div>{q.isLoading?<Spinner/>:q.isError?<ErrorNotice error={q.error}/>:tab==='blocks'?<div className="blocks-grid">{blocks.length?blocks.map((b:Row)=>{const initial=Number(b.initial_height_mm)||1;const remain=Number(b.remaining_height_mm);return <article className="block-card" key={b.id}><header><span className="block-code">{b.code}</span><Status value={b.status}/></header><div className="block-main"><div className="little-foam"/><div><h3>{productName(b.product,catalog)}</h3><p>{warehouseName(b.warehouse,catalog)}</p></div></div><div className="block-dimensions"><span>{l("طول × عرض")}</span><strong dir="ltr">{number(b.length_mm)} × {number(b.width_mm)} <small>mm</small></strong></div><div className="block-height"><span>{l("ارتفاع باقی‌مانده")}</span><strong>{number(remain/10)} <small>cm</small></strong></div><div className="progress-track"><span style={{width:`${Math.min(remain/initial*100,100)}%`}}/></div><p className="block-saleability"><span>{l("ارتفاع قابل فروش")}: <bdi>{number(["ready","reserved"].includes(b.status)?Math.max(0,remain-Number(b.reserved_height_mm))/10:0)} cm</bdi></span></p>{b.status==="curing"&&<p className="block-quality-note">{l("بلوک در حال عمل‌آوری است؛ ارتفاع موجود تا تأیید کیفیت قابل فروش نیست.")}</p>}{["inspection","hold"].includes(b.status)&&<p className="block-quality-note">{l("بلوک تحت بررسی کیفیت است؛ پیش از فروش، آزادسازی مجاز لازم است.")}</p>}<footer><span>{number(b.reserved_height_mm/10)} {l("cm رزرو")}</span>{hasPermission(business,'documents.print')&&<button className="icon-button" aria-label={l("چاپ برچسب بلوک")} title={l("چاپ برچسب بلوک")} onClick={()=>window.open(`/api/blocks/${b.id}/label/?business=${businessId}`,'_blank')}><Printer size={15}/></button>}{canAction('sale')&&['ready','reserved'].includes(b.status)&&Number(b.remaining_height_mm)>Number(b.reserved_height_mm)&&<button data-sale-link className="text-link" onClick={()=>perform('sale',{warehouse:b.warehouse,product:b.product,block:b.id})}>{l("برش و فروش")}<ArrowLeft size={14}/></button>}{Number(b.reserved_height_mm)>0&&<button className="text-link" onClick={()=>navigate('/operations?view=order_cutting')}>{l('بررسی رزرو سفارش')}</button>}</footer></article>}):<Empty/>}</div>:<Panel title={l("دفتر موجودی")} subtitle="موجودی هر محصول در انبار و اندازه مربوط"><InventoryRegister/></Panel>}<div className="info-card"><CircleHelp size={20}/><p>{l("سانتی‌مترهای اسفنج فقط در یک درجه و اندازه سازگار جمع می‌شوند. قطعات کوچک برای سفارش ضخیم به هم پیوسته نمی‌شوند.")}</p></div></>}
function Purchases(){return <><SectionHead title={l("خرید و تأمین‌کنندگان")} description="ورود مواد، بل تأمین‌کننده و پرداخت‌ها را بدون دوباره‌شماری مدیریت کنید." actions={<><ActionButton action="supplier_payment" secondary>{l("پرداخت به تأمین‌کننده")}</ActionButton><ActionButton action="purchase_receive">{l("دریافت خرید")}</ActionButton></>}/><details className="advanced-actions"><summary><Plus size={16}/>{l("عملیات بیشتر")}<ChevronDown size={15}/></summary><div className="action-row"><ActionButton action="purchase_order" secondary/><ActionButton action="purchase_bill" secondary>{l("ثبت بل تأمین‌کننده")}</ActionButton><ActionButton action="purchase_return" secondary>{l("برگشت خرید")}</ActionButton></div></details><PurchaseReviewPanel/><DocumentWorkspace tabs={[["purchase_receive","رسیدهای ورود خرید"],["purchase_order","سفارش‌های خرید"],["purchase_bill","بل‌های تأمین‌کنندگان"],["supplier_payment","پرداخت‌های تأمین‌کنندگان"]]}/></>}
function Transfers(){return <><SectionHead title={l("انتقال بین انبارها و شعب")} description="موجودی از ارسال تا تأیید دریافت، در مسیر قابل پیگیری است." actions={<><ActionButton action="transfer_receive" secondary>{l("تأیید دریافت")}</ActionButton><ActionButton action="transfer_dispatch">{l("انتقال جدید")}</ActionButton></>}/><div className="mode-banner"><ArrowRightLeft size={28}/><div><strong>{l("انتقال داخلی، فروش خارجی شرکت نیست.")}</strong><p>{l("بهای دفتری حفظ می‌شود. قیمت داخلی کابل در دفتر مدیریتی جدا قابل ثبت است.")}</p></div><Badge tone="blue">{l("بدون درآمد ساختگی")}</Badge></div><DocumentWorkspace tabs={[["transfer_dispatch","انتقالات ارسالی"],["transfer_receive","رسیدهای انتقال"]]}/><details className="advanced-actions"><summary><Plus size={16}/>{l("عملیات بیشتر")}<ChevronDown size={15}/></summary><div className="action-row"><ActionButton action="transfer_resolve" secondary/><ActionButton action="internal_charge_adjust" secondary/><ActionButton action="internal_settlement" secondary>{l("ثبت تسویه داخلی")}</ActionButton></div></details></>}
