function Employees(){return <EmployeeWorkspace/>}
const reports=[['summary','نمای کلی مالی'],['trial_balance','تراز آزمایشی'],['profit_loss','سود و زیان'],['balance_sheet','بیلانس'],['cash_flow','جریان نقدی'],['changes_equity','صورت تغییرات حقوق مالک'],['chart_of_accounts','چارت حساب‌ها'],['cash_balances','موجودی صندوق و بانک'],['receivables','طلب مشتریان'],['payables','بدهی تأمین‌کنندگان'],['inventory_reconciliation','تطبیق موجودی و حساب‌ها'],['employee_balances','مانده کارمندان'],['assets','دارایی‌های ثابت'],['general_ledger','دفتر کل'],['audit','رویدادها و بررسی'],['production_batches','گزارش بچ‌های تولید'],['production_waste','ضایعات تولید'],['stock_movements','گردش موجودی'],['block_history','تاریخچه بلوک‌ها'],['transfer_status','وضعیت انتقالات']];
function Accounting(){
 const{business,businessId,locationId}=useScope();const permission=(name:string)=>name==='cash_balances'?'finance.view':name==='audit'?'audit.view':name==='summary'?'reports.view':name==='receivables'?'sales.view':name==='payables'?'purchases.view':name==='employee_balances'?'payroll.view':name==='inventory_reconciliation'?'cost.view':['production_batches','production_waste','stock_movements','block_history','transfer_status'].includes(name)?'inventory.view':'accounting.view';
 const available=reports.filter(([id])=>hasPermission(business,permission(id)));const[report,setReport]=useState(new URLSearchParams(useLocation().search).get('report')||available[0]?.[0]||'summary');const[from,setFrom]=useState('');const[to,setTo]=useState('');const[compare,setCompare]=useState(false);const[compareFrom,setCompareFrom]=useState('');const[compareTo,setCompareTo]=useState('');const selected=available.some(r=>r[0]===report)?report:available[0]?.[0]||'summary';const q=useResource(selected==='audit'?'/api/audit/':`/api/reports/${selected}/?from=${from}&to=${to}${locationId&&!['trial_balance','balance_sheet','changes_equity'].includes(selected)?`&location=${locationId}`:''}${compare&&compareTo?`&compare_from=${compareFrom}&compare_to=${compareTo}`:''}`,!!available.length);
 if(!available.length)return <Empty text="گزارشی در محدوده دسترسی شما وجود ندارد"/>;
 return <div className="accounting-reports-page"><SectionHead title={l("حسابداری و گزارش‌ها")} description="گزارش‌های حاصل از اسناد واقعی، با ردپای قابل بررسی." actions={<><ActionButton action="journal_adjust" secondary>{l("سند اصلاحی")}</ActionButton>{hasPermission(business,'reports.export')&&selected!=='audit'&&<a className="button secondary" href={`/api/export/${selected}/?business=${businessId}&from=${from}&to=${to}${locationId&&!['trial_balance','balance_sheet','changes_equity'].includes(selected)?`&location=${locationId}`:''}${compare&&compareTo?`&compare_from=${compareFrom}&compare_to=${compareTo}`:''}`}><FileDown size={17}/>CSV</a>}<button className="button primary" onClick={()=>window.print()}><Printer size={17}/>{l("چاپ گزارش")}</button></>}/><div className="report-layout"><aside className="report-menu"><span className="sidebar-caption">{l("گزارش‌های مالی و عملیاتی")}</span>{available.map(([id,name])=><button key={id} className={selected===id?'active':''} onClick={()=>setReport(id)}><FileText size={16}/>{l(name)}<ArrowLeft size={14}/></button>)}</aside><Panel title={reports.find(r=>r[0]===selected)?.[1]} subtitle="ارقام ثبت‌شده در واحد پول پایه کسب‌وکار" action={<div className="report-dates"><CalendarInput ariaLabel="از تاریخ" value={from} onChange={setFrom}/><span>{l("تا")}</span><CalendarInput ariaLabel="تا تاریخ" value={to} onChange={setTo}/></div>}>{['profit_loss','balance_sheet','changes_equity'].includes(selected)&&<div className="comparison-controls"><label className="check-field"><input type="checkbox" checked={compare} onChange={e=>setCompare(e.target.checked)}/>{l('مقایسه با دوره دیگر')}</label>{compare&&<><CalendarInput ariaLabel={l('آغاز دوره مقایسه')} value={compareFrom} onChange={setCompareFrom}/><CalendarInput ariaLabel={l('پایان دوره مقایسه')} value={compareTo} required onChange={setCompareTo}/></>}</div>}{q.isLoading?<Spinner/>:q.isError?<ErrorNotice error={q.error} retry={()=>q.refetch()}/>:<>{!q.data?.statement&&<ReportPrintHeader title={reports.find(r=>r[0]===selected)?.[1]||selected} from={from} to={to} businessWide={["trial_balance","chart_of_accounts"].includes(selected)}/>}<ReportData data={q.data||{}}/></>}</Panel></div><details className="advanced-actions"><summary><Plus size={16}/>{l("عملیات بیشتر")}<ChevronDown size={15}/></summary><div className="action-row"><ActionButton action="period_close" secondary>{l("بستن دوره مالی")}</ActionButton><ActionButton action="period_reopen" secondary>{l("بازگشایی دوره")}</ActionButton><ActionButton action="asset_acquire" secondary>{l("ثبت دارایی")}</ActionButton><ActionButton action="asset_depreciate" secondary>{l("ثبت استهلاک")}</ActionButton><ActionButton action="inventory_write_down" secondary/><ActionButton action="receivable_writeoff" secondary/><ActionButton action="shared_cost_allocate" secondary/></div></details><div id="approvals"><ApprovalsPanel/></div></div>;
}
const fieldLabels:Record<string,string>={account:'حساب',code:'کد',name:'نام',debit:'بدهکار',credit:'بستانکار',balance:'مانده',amount:'مبلغ',total:'مجموع',sales:'فروش',revenue:'درآمد',expenses:'مصارف',profit:'سود',cogs:'بهای فروش',cash:'نقد',inventory:'موجودی',assets:'دارایی‌ها',liabilities:'بدهی‌ها',equity:'حقوق مالک',receivables:'طلب مشتریان',payables:'بدهی تأمین‌کنندگان',employee:'کارمند',party:'طرف حساب',advance:'پیش‌پرداخت',payable:'قابل پرداخت',date:'تاریخ',number:'شماره',description:'شرح',quantity:'مقدار',value:'ارزش',product:'محصول',warehouse:'انبار',difference:'اختلاف',inventory_value:'ارزش موجودی',gl_balance:'مانده دفتر کل',balanced:'تراز',net_profit:'سود خالص',cash_balance:'موجودی نقد',gross_profit:'سود ناخالص',rows:'ردیف‌ها',details:'جزئیات',location:'موقعیت',line:'خط محصول',source:'سند مرجع',kind:'نوع',action:'عملیات',actor:'کاربر',created_at:'زمان',outstanding:'مانده قابل دریافت',paid:'پرداخت‌شده',cost:'بها',accumulated_depreciation:'استهلاک انباشته',net_book_value:'ارزش دفتری',supplier:'تأمین‌کننده',customer:'مشتری'};
function ReportData({data}:{data:Row}){
 const{catalog}=useScope();
 if(data.name==='chart_of_accounts')return <AccountBrowser data={data}/>;
 if(data.statement&&data.sections)return <FinancialStatement data={data}/>;
 const arrays=Object.entries(data).filter(([k,v])=>Array.isArray(v)&&k!=='columns');
 const scalar=Object.entries({...data,...(data.totals||{})}).filter(([k,v])=>!Array.isArray(v)&&typeof v!=='object'&&!['as_of','from','to','name','method','basis','note','truncated','statement','date_from','payroll_detail_included'].includes(k));
 return <div className="report-data">{!!scalar.length&&<div className="report-totals">{scalar.map(([k,v])=><div key={k}><span>{fieldLabels[k]||k.replaceAll('_',' ')}</span><strong className="numeric">{typeof v==='boolean'?(v?'بله':'خیر'):v!==''&&!Number.isNaN(Number(v))?number(v):displayValue(v)}</strong></div>)}</div>}
 {arrays.map(([key,array])=>{const records=(array as any[]).map(r=>typeof r==='object'?r:{value:r});const inferred=Array.from(new Set(records.flatMap(Object.keys))).filter(k=>!['id','business','data','metadata'].includes(k)).slice(0,10);const columns:Row[]=key==='rows'&&data.columns?data.columns:inferred.map(key=>({key,label:fieldLabels[key]||key.replaceAll('_',' ')}));return <div key={key} className="report-section">{arrays.length>1&&<h3>{fieldLabels[key]||key}</h3>}<DataTable data={records} columns={columns.map(c=>({key:c.key,label:fieldLabels[c.key]||c.label||c.key,render:r=>{const v=r[c.key];if(typeof v==='string'&&/^\d{4}-\d{2}-\d{2}(?:T.*)?$/.test(v))return displayValue(v);if(c.key==='group')return l(groupNames[String(v)]||String(v));if(c.key==='product')return productName(v,catalog);if(c.key==='warehouse')return warehouseName(v,catalog);if(typeof v==='object')return Array.isArray(v)?`${number(v.length)} ${l('مورد')}`:Object.entries(v||{}).map(([a,b])=>`${fieldLabels[a]||a}: ${displayValue(b)}`).join(' · ');return v!==null&&v!==''&&!Number.isNaN(Number(v))&&!['code','number','id'].includes(c.key)?number(v,3):l(String(v??'—'));}}))}/></div>})}{!arrays.length&&!scalar.length&&<Empty/>}</div>;
}
function SettingsPage(){
 const{catalog,business,notify,userId,businessId,locationId}=useScope();const qc=useQueryClient();const[resource,setResource]=useState('products');const navigate=useNavigate();const settingQuery=useLocation().search;const section=new URLSearchParams(settingQuery).get('section')||(hasPermission(business,'settings.manage')?'setup':hasPermission(business,'users.manage')?'access':'tax');const[adding,setAdding]=useState(false);const[editing,setEditing]=useState<Row|undefined>();
 const resources=[['products','محصولات و مواد'],['parties','مشتریان و تأمین‌کنندگان'],['employees','کارمندان'],['warehouses','انبارها'],['locations','موقعیت‌ها'],['accounts','حساب‌ها'],['tax_rules','قواعد مالیاتی'],...(String(business.manufacturing_mode).toLowerCase()==='bom'?[['boms','نسخه‌های فرمول']]:[])];
 const data=catalog[resource]||[];const fields=useMemo(()=>catalogFields(resource,catalog),[resource,catalog]);
 const columns=resource==='tax_rules'?[['name','نام'],['rate','نرخ فیصدی'],['effective_from','مؤثر از'],['effective_to','مؤثر تا'],['account_code','حساب']]:resource==='products'?[['code','کد'],['name','نام'],['kind','نوع'],['line','خط محصول'],['unit','واحد'],['price','نرخ فروش']]:resource==='parties'?[['name','نام'],['kind','نوع'],['phone','تلفن'],['address','آدرس'],['notes','یادداشت']]:resource==='employees'?[['name','نام'],['kind','نوع'],['rate','نرخ'],['advance_limit','حد پیش‌پرداخت']]:resource==='warehouses'?[['name','نام'],['kind','نوع'],['location','موقعیت']]:resource==='accounts'?[['number','شماره حساب'],['code','کد ثبت داخلی'],['name','نام'],['category','گروه'],['statement_group','گروه گزارش']]:resource==='memberships'?[['user','شناسه کاربر'],['role','نقش'],['all_locations','همه موقعیت‌ها'],['active','فعال']]:resource==='boms'?[['name','نام'],['version','نسخه'],['output_quantity','خروجی مرجع'],['approved','تأییدشده']]:[['name','نام'],['code','کد'],['id','شناسه']];
 return <><SectionHead title={l('تنظیمات کسب‌وکار')} description="تنظیمات را بر اساس کار مورد نظر انتخاب کنید؛ همه تغییرات مربوط همین تجارت است."/>
 <nav className="settings-sections" aria-label={l('بخش‌های تنظیمات')}>
 {([['tax','نسخه‌های مالیه افغانستان','منبع، تاریخ و تأیید قواعد مالیاتی'],['setup','راه‌اندازی و اطلاعات پایه','محصول، گدام، مالیات و تنظیم تجارت'],['access','کاربران و صلاحیت‌ها','نقش‌ها، محدوده و اجازه هر کار'],['print','چاپ، PDF و رسیدها','سربرگ، کاغذ، امضا و نمونه چاپ'],['finance','حساب‌ها و مانده آغازین','بانک، صندوق و تأیید معاملات'],['security','مصونیت و پشتیبان','امنیت حساب و نسخه پشتیبان']] as string[][]).filter(([key])=>key==='tax'?hasPermission(business,'accounting.view','accounting.tax_view','accounting.tax_manage','accounting.tax_confirm'):key==='access'?hasPermission(business,'users.manage'):key==='security'||hasPermission(business,'settings.manage')).map(([key,title,description])=><button key={key} aria-current={section===key?'page':undefined} className={section===key?'active':''} onClick={()=>navigate('/settings?section='+key)}><strong>{l(title)}</strong><small>{l(description)}</small></button>)}
 </nav>
 {section==='access'&&<AccessWorkspace/>}
 {section==='tax'&&<TaxSchedulesPanel key={`${businessId}:${locationId}`}/>}
 {section==='print'&&<PrintSettingsPanel/>}
 {section==='setup'&&hasPermission(business,'settings.manage')&&<><div className="access-toolbar"><div className="action-row"><NewBusiness/><ImportData/></div><button className="button primary" onClick={()=>{setEditing(undefined);setAdding(true);}}><Plus size={17}/>{l('افزودن')} {l(resources.find(r=>r[0]===resource)?.[1])}</button></div><div className="tabs setting-tabs">{resources.map(([id,caption])=><button key={id} className={resource===id?'active':''} onClick={()=>setResource(id)}>{l(caption)}</button>)}</div><Panel title={resources.find(r=>r[0]===resource)?.[1]} subtitle="برای ویرایش، روی ردیف مورد نظر کلیک کنید"><DataTable tableKey={'catalog:'+resource} preferenceScope={{userId,businessId,locationId}} inlineEdit={resource==='products'&&hasPermission(business,'settings.manage')?{mode:'master',eligible:()=>true,fields:[{key:'name',label:'نام محصول',required:true},{key:'price',label:'نرخ فروش (AFN)',type:'decimal',required:true}],save:async(row,changes)=>{await api.patch(`/api/catalog/products/${row.id}/`,changes);await qc.invalidateQueries();}}:undefined} bulkActions={resource==='products'&&hasPermission(business,'settings.manage')?[{id:'deactivate',label:'غیرفعال‌سازی انتخاب‌شده‌ها',eligible:row=>row.active!==false,confirm:'محصولات انتخاب‌شده غیرفعال شوند؟ اسناد قبلی تغییر نمی‌کند.',run:async selected=>{await api.post('/api/catalog-bulk/',{resource:'products',action:'deactivate',ids:selected.map(row=>row.id)});await qc.invalidateQueries();}}]:undefined} data={data} columns={columns.map(([key,label])=>({key,label,render:r=>typeof r[key]==='boolean'?l(r[key]?'بله':'خیر'):['kind','line','unit','category','statement_group'].includes(key)?l(catalogValueLabels[String(r[key])]||groupNames[String(r[key])]||String(r[key]??'—')):String(r[key]??'—')}))} onRow={r=>{if(resource==='boms'&&r.approved){notify('نسخه تأییدشده تغییر نمی‌کند؛ نسخه جدید ایجاد کنید.');return;}setEditing(r);setAdding(true);}}/></Panel><SetupChecklist/><BusinessControls/></>}
 {section==='finance'&&<><CreditPolicyPanel/><MoneyInstrumentsPanel/><Panel title="مانده‌های آغازین" subtitle="پس از شمارش و تأیید حسابدار؛ جدا از خرید، فروش و دریافت روزمره."><div className="opening-actions"><div className="action-row"><ActionButton action="stock_opening" secondary/><ActionButton action="opening_cash" secondary/><ActionButton action="opening_receivable" secondary/><ActionButton action="opening_payable" secondary/><ActionButton action="opening_employee_advance" secondary/></div></div></Panel><div id="approvals"><ApprovalsPanel/></div></>}
 {section==='security'&&<><RecoveryReadiness/><BackupSettingsPanel/><LANSettingsPanel key={businessId}/><UserSecurity/></>}{adding&&<Modal title={`${l(editing?'ویرایش':'افزودن')} ${l(resources.find(r=>r[0]===resource)?.[1])}`} onClose={()=>setAdding(false)} wide={resource==='boms'||resource==='memberships'}><CatalogEditor resource={resource} fields={fields} initial={editing} onSuccess={()=>{setAdding(false);notify('اطلاعات پایه ثبت شد.');qc.invalidateQueries({queryKey:['catalog']});}}/></Modal>}</>;
}

const statementGroups=[['current_assets','دارایی‌های جاری'],['noncurrent_assets','دارایی‌های غیرجاری'],['current_liabilities','بدهی‌های جاری'],['noncurrent_liabilities','بدهی‌های غیرجاری'],['equity','حقوق مالک'],['revenue','درآمد فروش'],['cost_of_sales','بهای فروش'],['administrative_expenses','مصارف اداری'],['selling_expenses','مصارف فروش'],['other_operating_expenses','سایر مصارف عملیاتی'],['other_operating_income','سایر درآمد عملیاتی'],['investing_income','درآمد سرمایه‌گذاری'],['finance_income','درآمد مالی'],['finance_costs','مصارف مالی'],['income_tax','مالیات بر درآمد']];
const catalogValueLabels:Record<string,string>={raw:'مواد اولیه',finished:'محصول نهایی',trim:'فرآورده جانبی',scrap:'ضایعات',service:'خدمت',sponge:'اسفنج',adhesive:'چسپ',shared:'عمومی / مشترک',cm:'سانتی‌متر',kg:'کیلوگرام',each:'عدد',monthly:'ماهانه',weekly:'هفته‌وار',daily:'روزانه',hourly:'ساعتی',part_time:'نیمه‌وقت',project:'پروژه‌ای',store:'انبار',floor:'کف تولید',transit:'در مسیر',customer:'مشتری',supplier:'تأمین‌کننده',asset:'دارایی',liability:'بدهی',equity:'حقوق مالک',income:'درآمد',expense:'مصرف'};
function catalogFields(resource:string,catalog:Row){const select=(key:string,label:string,options:string[])=>({key,label,type:'select' as const,required:true,options:options.map(v=>({value:v,label:catalogValueLabels[v]||v}))});if(resource==='tax_rules')return [{key:'name',label:'نام قاعده',required:true},{key:'rate',label:'نرخ فیصدی تأییدشده',type:'number' as const,required:true},{key:'effective_from',label:'مؤثر از',type:'date' as const,required:true},{key:'effective_to',label:'مؤثر تا (اختیاری)',type:'date' as const},{key:'account_code',label:'کد حساب مالیات',required:true,default:'TAX'}];if(resource==='products')return [{key:'code',label:'کد محصول',required:true},{key:'name',label:'نام محصول',required:true},select('kind','نوع',['raw','finished','trim','scrap','service']),select('line','خط محصول',['sponge','adhesive','shared']),select('unit','واحد',['cm','kg','each']),{key:'price',label:'نرخ فروش (AFN)',type:'number' as const,default:'0'}];if(resource==='parties')return [{key:'name',label:'نام',required:true},select('kind','نوع',['customer','supplier']),{key:'phone',label:'تلفن'},{key:'address',label:'آدرس'},{key:'notes',label:'یادداشت',type:'textarea' as const,span:true}];if(resource==='employees')return [{key:'name',label:'نام کارمند',required:true},select('kind','نوع همکاری',['monthly','daily','part_time','project']),{key:'location',label:'موقعیت',type:'select' as const,required:true,options:(catalog.locations||[]).map((l:Row)=>({value:l.id,label:l.name}))},{key:'rate',label:'نرخ (AFN)',type:'number' as const,required:true},{key:'advance_limit',label:'حد پیش‌پرداخت (AFN)',type:'number' as const,default:'0'},{key:'terms',label:'شرایط',type:'textarea' as const,span:true}];if(resource==='warehouses')return [{key:'name',label:'نام انبار',required:true},{key:'location',label:'موقعیت',type:'select' as const,required:true,options:(catalog.locations||[]).map((l:Row)=>({value:l.id,label:l.name}))},select('kind','نوع انبار',['store','floor','transit'])];if(resource==='accounts')return [{key:'number',label:'شماره حساب',required:true},{key:'statement_group',label:'گروه گزارش',type:'select' as const,required:true,options:statementGroups.map(([value,label])=>({value,label}))},{key:'code',label:'کد حساب',required:true},{key:'name',label:'نام حساب',required:true},select('category','گروه',['asset','liability','equity','income','expense'])];return [{key:'name',label:'نام',required:true},{key:'code',label:'کد',required:true}];}
function DocumentDetailPage(){
 const{documentId}=useParams();const navigate=useNavigate();const location=useLocation();const{businessId}=useScope();
 const match=/^\d+$/.test(documentId||'');const expected=new URLSearchParams(location.search).get('business');
 const q=useResource(`/api/documents/${documentId}/`,match&&(!expected||expected===businessId));
 if(expected&&expected!==businessId)return <Panel title={l("سند مربوط به تجارت انتخاب‌شده نیست")}><p>{l('تجارت مربوط به سند را از سرصفحه انتخاب کنید. دسترسی سرور همیشه بررسی می‌شود.')}</p><button className="button secondary" onClick={()=>navigate('/sales')}>{l('بازگشت')}</button></Panel>;
 if(!match)return <Empty text="سند پیدا نشد"/>;
 if(q.isLoading)return <Spinner/>;if(q.isError)return <ErrorNotice error={q.error} retry={()=>q.refetch()}/>;if(!q.data)return null;
 const from=location.state?.from;const fallback=['sale','sales_return','quotation','sales_order','receipt','customer_refund'].includes(q.data.kind)?'/sales':['purchase_bill','purchase_receive','supplier_payment','purchase_return'].includes(q.data.kind)?'/purchases':'/money';
 const back=()=>{if(typeof from==='string'&&from.startsWith('/')&&!from.startsWith('//')&&from!==location.pathname+location.search)navigate(from);else navigate(fallback);};
 return <DocumentView key={`${businessId}:${documentId}`} document={q.data} onClose={back}/>;
}
function DocumentFrame({title,subtitle,onClose,children}:{title:string,subtitle:string,onClose:()=>void,children:ReactNode}){return <article className="document-detail-page"><SectionHead title={title} description={subtitle} actions={<button className="button secondary document-back" onClick={onClose}><ArrowLeft size={17}/>{l('بازگشت')}</button>}/><div className="document-paper">{children}</div></article>;}
function DocumentView({document:initial,onClose}:{document:Row,onClose:()=>void}){
 const navigate=useNavigate();const review=useReview();const{catalog,businessId,business,perform,notify,showDocument}=useScope();const qc=useQueryClient();const q=useResource(`/api/documents/${initial.id}/`);const d=q.data||initial;const data=d.data||{};const result=d.result||{};const lines=d.state==='posted'?(result.lines||result.outputs||result.inputs||[]):(data.lines||data.inputs||[]);const lineColumns:Column[]=[{key:'product',label:'محصول',render:r=>r.product_name||productName(r.product,catalog)},{key:'quantity',label:'مقدار',render:r=>r.quantity!==undefined?`${number(r.quantity,3)} ${r.unit||catalog.products?.find((p:Row)=>p.id===Number(r.product))?.unit||''}`:r.thickness_mm?`${number(Number(r.thickness_mm)/10)} cm × ${number(r.sheet_count||1)}`:'—'}];if(lines.some((r:Row)=>r.unit_price!==undefined))lineColumns.push({key:'unit_price',label:'نرخ فروش',render:r=>money(r.unit_price)});if(lines.some((r:Row)=>r.amount!==undefined))lineColumns.push({key:'amount',label:'مبلغ ردیف',render:r=>money(r.amount)});if(lines.some((r:Row)=>Number(r.thickness_mm)>0))lineColumns.push({key:'thickness_mm',label:'ضخامت ورق',render:r=>r.thickness_mm?`${number(r.thickness_mm)} mm`:'—'});const[error,setError]=useState('');const[busy,setBusy]=useState(false);const[editing,setEditing]=useState(false);
 if(lines.some((r:Row)=>r.price_basis))lineColumns.push({key:'price_basis',label:'مبنای نرخ',render:r=>l(({catalog_match:'نرخ عمومی',agreement_match:'مطابق قرارداد مشتری',order_match:'مطابق سفارش',authorized_override:'تغییر نرخ مجاز'} as Record<string,string>)[r.price_basis]||'—')});
 const run=async(action:()=>Promise<void>)=>{setBusy(true);setError('');try{await action();}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setBusy(false);}};
 const upload=async(file:File)=>{const form=new FormData();form.append('document',String(d.id));form.append('file',file);await api.upload('/api/attachments/',form);qc.invalidateQueries({queryKey:[`/api/documents/${d.id}/`]});notify('پیوست به سند اضافه شد.');};
 if(q.isError)return <ErrorNotice error={q.error}/>;
 return <DocumentFrame title={d.number||'سند ثبت‌شده'} subtitle={`${l(operationLabels[d.kind]||d.kind)} · ${dateLabel(d.date)}`} onClose={onClose}><div className="document-view"><div className="document-top"><Brand/><Status value={d.state}/></div><div className="document-summary"><div><span>{l("طرف حساب")}</span><strong>{result.customer_snapshot?.name||result.supplier_snapshot?.name||result.party_snapshot?.name||d.party_name||d.employee_name||(d.party?partyName(d.party,catalog):data.customer_name||'—')}</strong></div><div><span>{l("مبلغ کل")}</span><strong>{money(d.amount)}</strong></div><div><span>{l("مانده")}</span><strong>{money(d.balance)}</strong></div><div><span>{l("انبار")}</span><strong>{warehouseName(d.warehouse,catalog)}</strong></div></div>
 <SalesFlowActions document={d} onNavigate={onClose}/>
 <OrderReadiness document={d}/>
 <div className="action-row"><CorrectionLink document={d}/></div>
 {lines.length>0&&<DataTable data={lines} columns={lineColumns}/>} {data.notes&&<p className="document-notes">{data.notes}</p>}
 <DocumentResultSummary result={result}/>
 {!d.sales_flow&&d.related_documents?.length>0&&<section className="document-related"><h3>{l('اسناد مرتبط')}</h3>{d.related_documents.map((r:Row)=><button className="button secondary small" key={r.id} onClick={()=>showDocument(r)}><FileText size={15}/><bdi>{r.number}</bdi><span>{l(operationLabels[r.kind]||r.kind)}</span></button>)}</section>}
 {result.outputs?.length>0&&result.inputs?.length>0&&<div className="document-inputs"><h3>{l('مواد مصرف‌شده واقعی')}</h3><DataTable data={result.inputs} columns={[{key:'product',label:'مواد اولیه',render:r=>r.product_name||productName(r.product,catalog)},{key:'quantity',label:'مقدار مصرف',render:r=>number(r.quantity,3)},{key:'warehouse',label:'انبار مصرف',render:r=>warehouseName(r.warehouse,catalog)}]}/></div>}
 {d.state==='draft'&&d.data?.document_capture&&<div className="draft-notice"><FileText size={20}/><div><strong>{l('مسوده بررسی‌شده از اصل سند')}</strong><p>{l('معلومات با مدرک اصلی تأیید شده است. ثبت نهایی فقط با صلاحیت عادی انجام می‌شود؛ این مسوده هنوز اثر مالی ندارد.')}</p></div></div>}
 {d.state==='draft'&&!d.data?.document_capture&&<div className="draft-notice"><FileText size={20}/><div><strong>{l("این سند پیش‌نویس است.")}</strong><p>{l("تا زمان ثبت نهایی، موجودی یا حساب‌ها تغییر نکرده‌اند.")}</p></div><button className="button secondary small" onClick={()=>setEditing(!editing)}>{l("ویرایش داده پیش‌نویس")}</button></div>}
 {editing&&<StructuredDraftEditor id={d.id} onClose={()=>setEditing(false)} onSaved={()=>qc.invalidateQueries({queryKey:[`/api/documents/${d.id}/`]})}/>}
 <DocumentTimeline id={d.id}/>
 <div className="attachment-section"><div className="line-header"><h3><Paperclip size={15}/>{l("پیوست‌های سند")}</h3>{hasPermission(business,'attachments.create')&&<label className="button secondary small file-upload"><Upload size={15}/>{l("افزودن پیوست")}<input type="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.csv" disabled={busy} onChange={e=>{const file=e.target.files?.[0];if(file)run(()=>upload(file));e.target.value='';}}/></label>}</div><div className="attachment-list">{(d.attachments||[]).map((a:Row)=><a key={a.id} href={`/api/attachments/${a.id}/?business=${businessId}`} target="_blank" rel="noreferrer"><FileDown size={16}/>{a.filename}</a>)}{!d.attachments?.length&&<span className="attachment-empty">{l("پیوستی ثبت نشده است.")}</span>}</div></div>
 {error&&<ErrorNotice error={error}/>}<div className="document-actions">{hasPermission(business,'documents.print')&&d.state!=='draft'&&<DocumentPrintControls document={d}/>}{d.kind==='sale'&&!d.sales_flow&&Number(d.balance)>0&&<button className="button primary" onClick={()=>{onClose();perform('receipt',{invoice:d.id,amount:d.balance});}}><Plus size={17}/>{l("دریافت وجه")}</button>}{d.state==='draft'&&<button className="button primary" disabled={busy} onClick={()=>run(async()=>{if(!await review({title:'ثبت نهایی پیش‌نویس',message:'مقادیر و حساب‌های این مسوده را بررسی کرده‌اید؟'}))return;const result=await api.post(`/api/documents/${d.id}/post/`,{});qc.invalidateQueries();notify(`${l('سند')} ${result.document.number} ${l('ثبت نهایی شد.')}`);navigate(`/documents/${result.document.id}?business=${businessId}`,{replace:true});})}><Check size={17}/>{l("ثبت نهایی پیش‌نویس")}</button>}</div></div></DocumentFrame>;
}
function DocumentResultSummary({result}:{result:Row}){
 const{catalog}=useScope();const labels:Record<string,{label:string,unit?:string}>={subtotal:{label:'مبلغ پیش از مالیه',unit:'AFN'},total:{label:'مبلغ نهایی',unit:'AFN'},paid:{label:'دریافت / پرداخت هنگام ثبت',unit:'AFN'},outstanding:{label:'مانده هنگام ثبت',unit:'AFN'},deposit_amount:{label:'اعتبار ایجادشده هنگام ثبت',unit:'AFN'},internal_charge:{label:'مبلغ داخلی مدیریتی',unit:'AFN'},remaining_internal_charge:{label:'مانده تسویه داخلی',unit:'AFN'},gross:{label:'معاش ناخالص',unit:'AFN'},net:{label:'معاش خالص',unit:'AFN'},advance_recovery:{label:'کسر پیش‌پرداخت',unit:'AFN'},outstanding_advance:{label:'پیش‌پرداخت باقیمانده',unit:'AFN'},total_cost:{label:'بهای کل تولید',unit:'AFN'},wip_remaining:{label:'بهای تولید در جریان باقیمانده',unit:'AFN'},main_height_mm:{label:'ارتفاع اصلی پس از اصلاح',unit:'mm'},top_height_mm:{label:'ارتفاع سربلوک',unit:'mm'},bottom_height_mm:{label:'ارتفاع کف بلوک',unit:'mm'},loss_mm:{label:'ضایعات برش',unit:'mm'},billable_cm:{label:'ارتفاع قابل بل',unit:'cm'},counted:{label:'موجودی شمارش‌شده',unit:'AFN'},variance:{label:'اختلاف شمارش',unit:'AFN'},statement_balance:{label:'مانده صورت‌حساب بانک',unit:'AFN'}};
 const summaries=Object.keys(labels).filter(k=>result[k]!==undefined&&result[k]!==null);return <>{(result.status||result.source||result.destination)&&<div className="document-context">{result.status&&<Status value={result.status}/>} {result.source&&<span>{l('از انبار')}: <strong>{warehouseName(result.source,catalog)}</strong></span>}{result.destination&&<span>{l('به انبار')}: <strong>{warehouseName(result.destination,catalog)}</strong></span>}</div>}{summaries.length>0&&<section className="document-snapshot-summary"><h3>{l('خلاصه سند هنگام ثبت')}</h3><p className="ledger-note">{l('این مبالغ مربوط به زمان ثبت همین سند است؛ مانده فعلی در بالای صفحه و دریافت‌ها و برگشت‌های بعدی در اسناد مرتبط دیده می‌شود.')}</p><div className="report-totals document-totals">{summaries.map(key=><div key={key}><span>{l(labels[key].label)}</span><strong className="numeric">{labels[key].unit==='AFN'?money(result[key]):number(result[key],3)}{labels[key].unit!=='AFN'&&<small> {labels[key].unit}</small>}</strong></div>)}</div></section>}</>;
}

